sp_widget.client_script:
api.controller = function($scope) {
  var c = this;
  c.open = false;
  c.submitted = false;
  c.saving = false;
  c.error = '';
  c.number = '';
  c.form = {};

  c.openForm = function() {
    c.open = true;
  };

  c.submit = function() {
    if (!c.form.patient_name) {
      c.error = 'Please enter the patient name.';
      return;
    }
    if (!c.form.patient_status) {
      c.error = 'Please select the patient status.';
      return;
    }
    c.error = '';
    c.saving = true;

    c.server.get({
      action: 'submit',
      patient_name: c.form.patient_name,
      patient_status: c.form.patient_status
    }).then(function(response) {
      c.saving = false;
      if (response.data.success) {
        c.number = response.data.number;
        c.submitted = true;
        c.form = {};
      } else {
        c.error = 'Could not save. Please try again.';
      }
    });
  };

  c.close = function() {
    c.open = false;
    c.submitted = false;
    c.error = '';
    c.number = '';
  };
};

sp_widget.css:
.pdc-card {
  background: #fff;
  border: 1px solid #5fa8a0;
  border-radius: 6px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.15);
  text-align: center;
  padding: 40px 25px;
  min-height: 200px;
  cursor: pointer;
  transition: box-shadow .2s, transform .2s;
}
.pdc-card:hover {
  box-shadow: 0 6px 16px rgba(0,0,0,0.2);
  transform: translateY(-3px);
}
.pdc-icon { font-size: 56px; color: #14323f; margin-bottom: 15px; }
.pdc-title { font-size: 20px; color: #14323f; margin: 0 0 8px; }
.pdc-desc { color: #333; margin: 0; }

.pdc-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.55);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
}
.pdc-modal {
  background: #fff;
  padding: 25px;
  width: 440px;
  max-width: 92%;
  max-height: 90vh;
  overflow-y: auto;
  border-radius: 8px;
}
.pdc-modal h4 { margin-top: 0; color: #14323f; }
.pdc-modal label { font-weight: 600; margin-top: 10px; display: block; }
.pdc-check label { font-weight: 600; }
.pdc-actions { text-align: right; margin-top: 15px; }
.pdc-success { font-size: 50px; color: #2e9e5b; margin-bottom: 10px; }

sp_widget.script:
(function() {
  var TABLE = 'x_snc_discharge_0_patient_details';

  // Patient Status choices ni table nunchi load chestundi
  data.statusChoices = [];
  var ch = new GlideRecord('sys_choice');
  ch.addQuery('name', TABLE);
  ch.addQuery('element', 'patient_status');
  ch.addQuery('inactive', false);
  ch.orderBy('sequence');
  ch.query();
  while (ch.next()) {
    data.statusChoices.push({
      value: ch.getValue('value'),
      label: ch.getValue('label')
    });
  }

  // Submit
  if (input && input.action == 'submit') {
    var gr = new GlideRecord(TABLE);
    gr.initialize();
    gr.setValue('patient_name', input.patient_name);
    gr.setValue('patient_status', input.patient_status);
    var sysId = gr.insert();

    if (sysId) {
      data.success = true;
      var saved = new GlideRecord(TABLE);
      if (saved.get(sysId))
        data.number = saved.getValue('number');
    } else {
      data.success = false;
    }
  }
})();
